args:
$ErrorActionPreference = 'Stop'
$sdk = 'C:/Program Files (x86)/Android/android-sdk'
$adb = Join-Path $sdk 'platform-tools/adb.exe'
$emulator = Join-Path $sdk 'emulator/emulator.exe'
$avd = 'pixel_5_-_api_30_0'
$serial = 'emulator-5554'

$devices = & $adb devices
if (-not ($devices -match '^emulator-5554\s')) {
    Start-Process -WindowStyle Normal -FilePath $emulator -ArgumentList '-avd', $avd, '-port', '5554'
}

$deadline = (Get-Date).AddMinutes(3)
while ((Get-Date) -lt $deadline) {
    $devices = & $adb devices
    if ($devices -match '^emulator-5554\s+device\s*$') {
        $name = (& $adb -s $serial shell getprop ro.boot.qemu.avd_name | Out-String).Trim()
        if ($name -and $name -ne $avd) {
            throw "Port $serial belongs to a different emulator."
        }
        if ((& $adb -s $serial shell getprop sys.boot_completed) -eq '1') {
            Write-Output "Android emulator is ready on $serial."
            exit 0
        }
    }
    Start-Sleep -Seconds 2
}
throw 'Android emulator did not finish booting within three minutes.'

